"""`python -m duosim.platform new <id>`: generate a simulator plug-in that already passes conformance."""

from __future__ import annotations

from pathlib import Path

from .registry import ID_RE

_INIT = '''\
"""{name} - generated by `python -m duosim.platform new`.

Edit `Model` (state, physics, tags, commands) and keep the contract:
    python -m duosim.platform check {sim_id} --dir {parent}
"""

from __future__ import annotations

from typing import Any

from duosim.platform.registry import CommandRejected, CommandSpec, Manifest, Plugin, SimpleModel, TagSpec


class Model(SimpleModel):
    manifest = Manifest(
        id={sim_id!r},
        name={name!r},
        domain={domain!r},
        version="0.1.0",
        description={description!r},
        dt=1.0,  # seconds of simulated time per step
        tags=(
            TagSpec("x", "", "process value", None, None),
            TagSpec("setpoint", "", "set-point"),
        ),
        commands=(CommandSpec("set_setpoint", "change the set-point", {{"value": "number"}}),),
        # what the Design Studio should draw for this simulator's 3-D model
        design_prompt={design_prompt!r},
    )

    TAU = 30.0  # s, first-order lag: replace with your physics

    def initial_state(self) -> dict[str, Any]:
        return {{"x": 0.0, "u": 1.0}}

    def advance(self, dt: float) -> None:
        s = self.state
        s["x"] += (s["u"] - s["x"]) * dt / self.TAU

    def read_tags(self) -> dict[str, float]:
        return {{"x": self.state["x"], "setpoint": self.state["u"]}}

    def handle(self, name: str, args: dict[str, Any]) -> dict[str, Any]:
        if name == "set_setpoint":
            if not -1e6 <= args["value"] <= 1e6:
                raise CommandRejected("set_setpoint: value out of range")
            self.state["u"] = float(args["value"])
        return {{}}


PLUGIN = Plugin(Model.manifest, Model)
'''

_TEST = '''\
"""Conformance + behaviour tests for {sim_id}.  Run:  pytest {sim_id}"""

import importlib.util
from pathlib import Path

from duosim.platform.registry import conformance

spec = importlib.util.spec_from_file_location("plugin_under_test", Path(__file__).parent / "__init__.py")
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)


def test_conforms_to_the_platform_contract():
    assert conformance(mod.PLUGIN) == []


def test_state_relaxes_to_the_setpoint():
    s = mod.PLUGIN.create(seed=1)
    s.command("set_setpoint", value=5.0)
    s.step(600)
    assert abs(s.tags()["x"] - 5.0) < 1e-3
'''

_README = """\
# {name}

Generated plug-in (`{sim_id}`, domain: {domain}).

1. Edit `__init__.py`: state in `initial_state`, physics in `advance`, outputs in `read_tags`,
   operator/trainer actions in `handle`. Declare every tag and command in the manifest.
2. `python -m duosim.platform check {sim_id} --dir {parent}` - the contract check (tags match the
   manifest, finite values, snapshot/restore reproduces the future, bad commands are rejected).
3. Start the server with `DUOSIM_SIMULATORS_DIR={parent}`; the simulator appears under
   `GET /api/platform/simulators`.
4. Generate its 3-D model in the Design Studio (`/design`) from `manifest.design_prompt`.

Plug-ins are trusted code installed by the operator; they are not sandboxed.
"""


def render(sim_id: str, name: str, domain: str, parent: str = "simulators") -> dict[str, str]:
    if not ID_RE.match(sim_id):
        raise ValueError(f"id {sim_id!r} must match {ID_RE.pattern} (lowercase letters, digits, underscore)")
    name = " ".join(name.split())[:80] or sim_id.replace("_", " ").title()
    domain = " ".join(domain.split())[:60] or "process"
    fields = {
        "sim_id": sim_id,
        "name": name,
        "domain": domain,
        "parent": parent,
        "description": f"{name} ({domain}).",
        "design_prompt": f"Describe the main equipment of the {name} here, in one paragraph, with sizes.",
    }
    return {
        "__init__.py": _INIT.format(**fields),
        f"test_{sim_id}.py": _TEST.format(**fields),
        "README.md": _README.format(**fields),
    }


def write(directory: str | Path, sim_id: str, name: str = "", domain: str = "") -> Path:
    parent = Path(directory)
    target = parent / sim_id
    if target.exists():
        raise FileExistsError(f"{target} already exists; refusing to overwrite")
    files = render(sim_id, name, domain, parent.as_posix())
    target.mkdir(parents=True)
    for fname, content in files.items():
        (target / fname).write_text(content)
    return target
